add_action( 'init', 'perfectpixel_sale_badge_beside_price_setup' );
add_filter( 'woocommerce_get_price_html', 'perfectpixel_sale_badge_beside_price', 20, 2 );
add_action( 'wp_head', 'perfectpixel_sale_badge_beside_price_css' );

function perfectpixel_sale_badge_beside_price_setup() {
	remove_action( 'woocommerce_before_single_product_summary', 'woocommerce_show_product_sale_flash', 10 );
}

function perfectpixel_sale_badge_beside_price( $html, $product ) {
	if ( is_admin() || wp_doing_ajax() || ! is_product() || get_queried_object_id() !== $product->get_id() || ! $product->is_on_sale() || did_action( 'woocommerce_after_single_product_summary' ) ) {
		return $html;
	}
	$badge = '<span class="onsale">' . esc_html__( 'Sale!', 'woocommerce' ) . '</span>';
	return $html . ' ' . apply_filters( 'woocommerce_sale_flash', $badge, get_post( $product->get_id() ), $product );
}

function perfectpixel_sale_badge_beside_price_css() {
	if ( function_exists( 'is_product' ) && is_product() ) {
		echo '<style>.summary .price .onsale{position:static;display:inline-block;min-width:0;min-height:0;margin:0 0 0 .5em;padding:.1em .6em;line-height:1.5;font-size:.6em;vertical-align:middle;border-radius:3px}</style>';
	}
}
